  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Rac-thalidomide in fasting healthy volunteers showed probably high absolute oral bioavailability of 80–100% at low doses, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Ampicillin in fasting healthy male subjects had an oral bioavailability of 62 ± 17% versus intravenous administration, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Ciramadol showed oral bioavailability of 80 ± 7% in patients with cirrhosis, supporting high oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Proguanil has an absolute oral bioavailability as high as 60% and is rapidly and extensively absorbed regardless of food intake, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "PNU-96391 had an absolute oral bioavailability of 0.6 (60%) after oral versus intravenous dosing in healthy volunteers, clearly above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Clopenthixol is reported to have an oral bioavailability of 40–60%, providing additional high-bioavailability evidence from a lipophilic, structurally complex molecule.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability values well above 20% (approximately 40–100%), and no affirmative low-bioavailability evidence was provided. The unfavorable solubility prior is not sufficient to override this consistent experimental direction, so the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is available for the query molecule itself.",
    "The query is a highly lipophilic, poorly soluble naphthoquinone; none of the analogues share this exact acidic enol/naphthoquinone scaffold.",
    "Fasted-state conditions are explicitly matched by only some records; food effects and formulation effects on the query remain uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

